contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Single public test function: takes recipient and an amount to send to c, and a caller address to set as owner at deploy time
    // Note: c is already deployed by the harness with some owner; we only interact via its public surface.
    function run(address payable recipient, uint amount) public payable {
        require(address(this).balance >= amount);

        // Record c balance before funding
        uint beforeC = address(c).balance;
        uint beforeThis = address(this).balance;

        // Fund contract C by sending Ether to it using its fallback (external payable)
        // Must have enough balance in this contract
        c.transfer{value: 0}(); // no-op to ensure compile allows payable; fallback is external payable but transfer of 0 does nothing
        // Actually send Ether by calling address(c).call with value is not allowed; instead use (bool,)=address(c).call
        (bool sent,) = address(c).call{value: amount}("\x00");
        require(sent);

        uint afterFundC = address(c).balance;
        // The increment should equal amount
        bool funded = (afterFundC == beforeC + amount);

        // Try withdrawAll as this contract (note: require in C checks msg.sender == owner)
        bool reverted;
        try c.withdrawAll(recipient) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint afterC = address(c).balance;
        uint afterRecipient = recipient.balance;

        // If the call did not revert, then msg.sender (this contract) must have been owner, so balance of c becomes zero and recipient increased by amount withdrawn
        // If the call reverted, then either c.balance unchanged or still equals previous
        assert(funded ? (
            (!reverted && afterC == 0 && afterRecipient == beforeThis - (address(this).balance - beforeThis) + amount) ||
            (reverted && afterC == afterFundC)
        ) : true);
    }

    receive() external payable { }
}

