contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    // single public test function taking parameters: recipient, ownerCaller flag, and amount to fund c
    function run(address payable recipient, bool callAsOwner, uint fundAmount) public payable {
        require(address(this).balance >= fundAmount);
        // fund the contract c with fundAmount so address(c).balance > = 0
        if (fundAmount > 0) {
            c.fallback{value: fundAmount}();
        }
        // record before-values
        uint beforeBalance = address(c).balance;
        address beforeOwner = c.owner();

        // prepare caller: if callAsOwner is true, we must call withdrawAll from owner address
        // deployer of c is external; but we cannot change msg.sender here. However, owner is a public variable set in constructor of C at deployment.
        // We cannot change msg.sender for calls, so emulate by only calling withdrawAll from this contract (msg.sender == this).
        // The rule must therefore relate to whether this contract is the recorded owner.
        bool reverted;
        // attempt the call; capture revert
        try c.withdrawAll(recipient) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint afterBalance = address(c).balance;
        address afterOwner = c.owner();

        // General rule: if this contract was owner before the call, the call must not revert, all funds moved to recipient (c balance zero), and owner unchanged.
        // If this contract was not owner before the call, the call must revert and c balance unchanged and owner unchanged.
        if (beforeOwner == address(this)) {
            assert(reverted == false && afterBalance == 0 && afterOwner == beforeOwner);
        } else {
            assert(reverted == true && afterBalance == beforeBalance && afterOwner == beforeOwner);
        }
    }
    receive() external payable { }
}

