contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // run a single test: try withdrawAll with a given ownerCandidate and recipient and an amount sent earlier
    function run(address ownerCandidate, address payable recipient, uint256 fundAmount, bool sendAsOwner) public payable {
        require(address(this).balance >= fundAmount);

        // Setup: deployer of c is outside control; we only interact via public functions.
        // We first check reported owner before any funding/withdrawal.
        address reportedOwner = c.owner();

        // Fund the contract c by sending Ether from this test contract
        // Ensure we have balance; transfer by calling fallback payable
        // Must use call since c has fallback payable
        (bool ok,) = address(c).call{value: fundAmount}("");
        require(ok);

        // Record contract balance before withdraw attempt
        uint256 beforeBalance = address(c).balance;

        // Decide who tries to withdraw: if sendAsOwner==true, we want the owner to call withdrawAll;
        // but we cannot change msg.sender of c; the InvMutTest contract is the caller in all calls.
        // So model: if reportedOwner == address(this) then this contract is owner and withdraw should succeed,
        // otherwise it should revert. We call and capture revert via try/catch pattern.
        bool reverted;
        try c.withdrawAll(recipient) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // After attempt, read resulting owner and balance
        address afterOwner = c.owner();
        uint256 afterBalance = address(c).balance;

        // If this contract is owner (reportedOwner == address(this)), withdrawAll must not revert,
        // and contract balance must become zero and recipient must be credited with the funds (address(this) balance increases accordingly).
        // Otherwise the call must revert and contract balance must remain unchanged.
        if (reportedOwner == address(this)) {
            // When owner called, it should succeed and drain the contract
            assert(reverted == false && afterBalance == 0 && beforeBalance >= afterBalance);
        } else {
            // When non-owner called, it should revert and contract balance unchanged
            assert(reverted == true && afterBalance == beforeBalance);
        }
    }

    receive() external payable {}
}

