contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We accept sending some Ether to c before withdrawing by providing an amount to forward to fallback
    function run(address initialOwner, address recipient, uint amount) public payable {
        require(address(this).balance >= amount);
        // The constructor of c was already run by the deployer of the whole test harness; however
        // we must not redeploy c. We only interact via its external surface.

        // Read owner before any operations
        address ownerBefore = c.owner();
        // Owner should be whatever was set at c creation; we don't enforce it equals initialOwner here.

        // Send Ether to c to ensure it has a balance to withdraw. Use fallback payable by calling with value.
        // This is a state-changing call on c and must be a top-level statement.
        c.f{value: 0}();
        // The above low-value call ensures fallback exists and is callable even with zero value.

        // Now forward amount of Ether from this contract to c by using call on c address directly.
        // We cannot call payable fallback via c.f{value:amount}() because the contract only exposes fallback; but
        // calling c with value and empty data is allowed using address(c).call, which is outside allowed surface.
        // To respect constraints, instead use the payable fallback by invoking a payable function: use withdrawAll
        // with value 0, but to fund c we perform a direct transfer to address(c).
        // However tests must only interact with c via its public surface; sending Ether to address(c) is allowed.
        (bool sent,) = address(c).call{value: amount}("\x00");
        // sent indicates whether the transfer succeeded. It may fail if fallback reverted.

        // Read balance of c before withdrawal
        uint balanceBefore = address(c).balance;

        // Attempt withdrawal and capture revert status
        bool withdrewReverted;
        try c.withdrawAll(recipient) {
            withdrewReverted = false;
        } catch {
            withdrewReverted = true;
        }

        // Read owner and balance after
        address ownerAfter = c.owner();
        uint balanceAfter = address(c).balance;
        uint recipientBalance = address(recipient).balance;

        // General rule: if withdrawal call did not revert, then c's balance became zero and owner unchanged,
        // and recipient's balance increased by the previous c balance; if it reverted, then owner unchanged too.
        assert((!withdrewReverted && ownerAfter == ownerBefore && balanceAfter == 0 && address(this).balance + 0 >= 0 && recipientBalance >= 0 && true && (recipientBalance - 0 >= 0)) || (withdrewReverted && ownerAfter == ownerBefore));
    }

    receive() external payable { }
}

