    constructor(C _c) { c = _c; }
    function run(address caller, address recipient, uint256 fund) public payable {
        require(address(this).balance >= fund);
        // fund the contract c from this test contract
        c.fallback{value: fund}();

        // record before-values
        address ownerBefore = c.owner();
        uint256 balanceBefore = address(c).balance;
        // Attempt withdrawAll as the InvMutTest contract (which is msg.sender for calls)
        bool reverted;
        try c.withdrawAll(recipient) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 balanceAfter = address(c).balance;
        // If caller (msg.sender) equals ownerBefore then call must not revert and balance becomes 0 (fund moved out)
        // Otherwise call must revert and balance must be unchanged.
        // Note: here msg.sender for the withdrawAll call is this contract (InvMutTest). So we compare ownerBefore to address(this).
        assert((ownerBefore == address(this) && reverted == false && balanceAfter == 0) || (ownerBefore != address(this) && reverted == true && balanceAfter == balanceBefore));
    }
    receive() external payable {}
}

