contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function taking parameters: caller address to act as owner, recipient, and an amount
    // We cannot change msg.sender when calling c from here (calls originate from this contract),
    // so to simulate owner vs non-owner we deploy c externally with its constructor already run by the harness.
    // For the test we accept a boolean isOwner indicating whether the caller should match c.owner().
    function run(address payable recipient, uint256 amount, bool expectSenderIsOwner) public payable {
        require(address(this).balance >= amount);

        // read owner and c balance before attempt
        address ownerBefore = c.owner();
        uint256 balanceBefore = address(c).balance;

        // send Ether into c so balance may be nonzero
        if (amount > 0) {
            // transfer Ether into c using the fallback
            (bool ok,) = address(c).call{value: amount}("\x00");
            // ignore ok; fallback is payable so normally ok == true
        }

        // Recompute balance after funding
        uint256 balanceAfterFund = address(c).balance;

        // Attempt withdrawal: since calls to c originate from this contract, msg.sender == address(this)
        // So withdrawal should succeed iff address(this) == ownerBefore. We capture revert via try/catch.
        bool reverted;
        try c.withdrawAll(recipient) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 balanceAfter = address(c).balance;

        // General rule: withdrawAll only succeeds when msg.sender == owner. Therefore:
        // - If address(this) equals the recorded ownerBefore, the call must not revert and the contract's balance must drop by the withdrawn amount (all funds sent to recipient).
        // - If address(this) is not the ownerBefore, the call must revert and the contract balance must remain unchanged.
        if (address(this) == ownerBefore) {
            // must not revert
            assert(reverted == false);
            // when successful, contract balance should be zero (withdrawAll transfers full balance)
            assert(balanceAfter == 0);
            // and it must have decreased compared to before the withdrawal (unless it was already zero)
            assert(balanceAfter <= balanceAfterFund);
        } else {
            // must revert
            assert(reverted == true);
            // balance must remain the same as before the attempted withdrawal
            assert(balanceAfter == balanceAfterFund);
        }
    }

    receive() external payable {}
}

