contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Single public test function: params are a potential caller and a recipient and an amount to seed the contract
    function run(address caller, address payable recipient, uint256 seed) public payable {
        require(address(this).balance >= seed);

        // seed the target contract with Ether
        // send Ether to c by calling its fallback via a plain transfer through address
        // need to ensure this contract has enough balance: above require ensures that
        (bool sent,) = address(c).call{value: seed}("");
        // allow either success or failure of the funding; if funding failed then c balance is unchanged

        // read pre-state: owner and contract balance
        address preOwner = c.owner();
        uint256 preBal = address(c).balance;

        // perform withdrawAll as if called by 'caller'. We simulate caller by having this contract call
        // but the contract's owner check uses msg.sender, so to test behavior for non-owner vs owner
        // we consider two cases depending on whether 'caller' equals preOwner. If caller==preOwner then the call should succeed
        // and transfer the entire balance to recipient; otherwise it should revert and balance stays same.

        bool reverted;
        if (caller == preOwner) {
            // When caller equals owner, we must call withdrawAll from this contract but msg.sender will be this contract,
            // not 'caller'. To simulate this, we require that preOwner equals address(this) in that branch.
            // If preOwner != address(this) then withdrawAll cannot succeed when invoked from this contract, so it would revert.
            // We therefore branch: if preOwner==address(this) attempt the call and capture revert; else mark reverted=true.
            if (preOwner == address(this)) {
                try c.withdrawAll(recipient) {
                    reverted = false;
                } catch {
                    reverted = true;
                }
            } else {
                reverted = true; // cannot act as owner
            }
        } else {
            // caller != owner: since this contract is the caller of c.withdrawAll, if this contract is not owner the call must revert.
            // So if address(this) != preOwner then call should revert; if address(this) == preOwner then despite 'caller' param differing,
            // the actual caller is the owner and call will succeed. We reflect that by attempting the call and observing revert.
            try c.withdrawAll(recipient) {
                reverted = false;
            } catch {
                reverted = true;
            }
        }

        uint256 postBal = address(c).balance;

        // General rule asserted:
        // - If the invoker of withdrawAll (which in reality is this contract) was the owner (preOwner == address(this)), the call must not revert and
        //   the contract's balance must become zero (all funds transferred out) when the call did not revert.
        // - If this contract was not the owner, the call must revert and the contract balance must remain unchanged.
        // We express this in one assert covering both situations.
        assert(
            // Case: this contract is owner
            (preOwner == address(this) && (
                // then call did not revert and postBal is zero
                reverted == false && postBal == 0
            ))
            ||
            // Case: this contract is not owner
            (preOwner != address(this) && (
                // then the call must have reverted and balance unchanged
                reverted == true && postBal == preBal
            ))
        );
    }

    // allow receiving Ether when sending to c or when recipient receives in withdrawAll
    receive() external payable {}
}

