contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // run takes the recipient address and an amount to fund c before the withdrawal
    function run(address payable recipient, uint256 fundAmount) public payable {
        require(address(this).balance >= fundAmount);

        // fund the target contract c by sending Ether to it via this contract
        // send Ether directly to c using low-level call to trigger fallback
        (bool sent,) = address(c).call{value: fundAmount}("");
        // funding might succeed or fail (e.g., if fallback reverted), record as boolean
        bool funded = sent;

        // read observable before-values
        address ownerBefore = c.owner();
        uint256 balanceBefore = address(c).balance;
        // sanity: balanceBefore should equal fundAmount if funding succeeded, else 0

        // attempt withdrawAll and record whether it reverted
        bool withdrewReverted;
        try c.withdrawAll(recipient) {
            withdrewReverted = false;
        } catch {
            withdrewReverted = true;
        }

        // read after-values
        address ownerAfter = c.owner();
        uint256 balanceAfter = address(c).balance;
        uint256 recipientBalanceAfter = address(recipient).balance;

        // General property asserted:
        // - The owner field is never changed by withdrawAll (ownerBefore == ownerAfter)
        // - withdrawAll must revert whenever msg.sender (this contract) is not the owner
        //   and must not revert when msg.sender equals owner. Because calls come from this contract,
        //   success implies this contract was ownerBefore. If withdraw succeeded then balanceAfter == 0
        //   and recipient's balance increased by balanceBefore.
        assert(
            ownerBefore == ownerAfter
            && (
                (withdrewReverted && ownerBefore != address(this))
                || (!withdrewReverted && ownerBefore == address(this) && balanceAfter == 0 && recipientBalanceAfter >= balanceBefore)
            )
        );
    }

    // allow this contract to receive Ether
    receive() external payable {}
}

