    // run takes an owner address (to set up contract was deployed with), a sender address candidate (we simulate by whether run tries withdraw via owner or not), a recipient, and an amount to fund C.
    // We cannot change msg.sender when calling c (it's this contract), so to simulate owner vs non-owner we rely on c.owner() getter and compare.
    function run(address ownerCandidate, bool callAsOwner, address payable recipient, uint amount) public payable {
        require(address(this).balance >= amount);
        // initial observed values
        address beforeOwner = c.owner();
        uint beforeBal = address(c).balance;

        // Fund contract C by sending Ether from this test to c
        // Must ensure this test has enough balance (checked above)
        (bool sent,) = address(c).call{value: amount}("");
        // ignore send success: fallback is payable so should succeed

        uint fundedBal = address(c).balance;

        // Decide whether to attempt withdraw: only owner (msg.sender==owner) can succeed.
        // Since all calls to c come from this contract, success depends on c.owner() == address(this).
        // We simulate two cases: if callAsOwner==true we require that c.owner()==address(this) to exercise success path; otherwise exercise non-owner path.
        if (callAsOwner) {
            // Precondition: make this contract the owner by deploying C with ownerCandidate == address(this).
            // The checker deploys a fresh C; we cannot redeploy it here. So enforce that provided ownerCandidate equals this contract and matches c.owner().
            require(beforeOwner == address(this));
        } else {
            require(beforeOwner != address(this));
        }

        // Attempt withdrawAll and capture whether it reverted
        bool reverted;
        try c.withdrawAll(recipient) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint afterBal = address(c).balance;
        uint recipientBal = address(recipient).balance;

        // General rule:
        // - If call did not revert, then before-funded balance must have moved entirely to recipient (contract balance decreased by that amount to zero), i.e., afterBal == 0 and recipient's balance increased by (fundedBal - beforeBal).
        // - If call reverted, contract balance must be unchanged (afterBal == fundedBal).
        // We express recipient increase using only observable balances (we compare recipientBal against 0 when funded amount was zero vs non-zero) but to stay general we compute delta.
        uint expectedTransfer = fundedBal - beforeBal;
        // Note: if expectedTransfer == 0, withdrawAll when called by owner will leave balances zero change but still satisfy rules.
        assert(
            (!reverted && afterBal == 0 && recipientBal >= expectedTransfer) || (reverted && afterBal == fundedBal)
        );
    }

    receive() external payable {}
}

